    pos.y += cos(uTime * 1.55 + phase * 1.1) * uSwayAmp * tipFactor;
    pos.z += sin(uTime * 2.20 + phase * 0.8) * (uSwayAmp * 0.45) * tipFactor;

    vWorldPos = pos;
